#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
//! The tidy sample board shipped as `examples/sample-board.circuito-pcb`.
//!
//! The file is generated by [`sample_board`]; the test fails when the file and the generator
//! disagree. After changing the generator, run
//! `CIRCUITO_UPDATE_EXAMPLES=1 cargo test -p circuito-pcb --test sample_board` to rewrite it.

use circuito_pcb::board::*;
use circuito_pcb::drc::{check_profile, run_drc, CapabilityProfile};
use circuito_pcb::geom::Point;
use circuito_pcb::layer::{Layer, Side};
use circuito_pcb::units::MM;
use circuito_pcb::{excellon, gerber};

fn mm(x: f64, y: f64) -> Point {
    Point::new(
        (x * MM as f64).round() as i64,
        (y * MM as f64).round() as i64,
    )
}

fn len(x: f64) -> i64 {
    (x * MM as f64).round() as i64
}

struct Ids(u64);

impl Ids {
    fn next(&mut self) -> Id {
        self.0 += 1;
        Id(self.0)
    }
}

fn smd(ids: &mut Ids, number: &str, net: u32, at: Point) -> Pad {
    Pad {
        id: ids.next(),
        number: number.into(),
        kind: PadKind::Smd,
        shape: PadShape::Rect,
        position: at,
        rotation: 0,
        size: Size {
            w: len(0.9),
            h: len(1.0),
        },
        drill: None,
        net: Some(NetId(net)),
        mask: true,
        paste: true,
        mask_margin: None,
        paste_margin: None,
    }
}

fn header_pad(ids: &mut Ids, number: &str, net: u32, at: Point) -> Pad {
    Pad {
        id: ids.next(),
        number: number.into(),
        kind: PadKind::ThroughHole,
        shape: PadShape::Circle,
        position: at,
        rotation: 0,
        size: Size {
            w: len(1.8),
            h: len(1.8),
        },
        drill: Some(Drill {
            diameter: len(1.0),
            slot_length: None,
        }),
        net: Some(NetId(net)),
        mask: true,
        paste: false,
        mask_margin: None,
        paste_margin: None,
    }
}

fn footprint(
    ids: &mut Ids,
    reference: &str,
    value: &str,
    package: &str,
    at: Point,
    pads: Vec<Pad>,
) -> Footprint {
    Footprint {
        id: ids.next(),
        reference: reference.into(),
        value: value.into(),
        package: package.into(),
        position: at,
        rotation: 0,
        side: Side::Front,
        pads,
        courtyard: None,
        graphics: vec![],
        texts: vec![],
        exclude_from_bom: false,
        exclude_from_pos: false,
    }
}

fn segment(ids: &mut Ids, net: u32, layer: Layer, width: f64, a: Point, b: Point) -> Track {
    Track {
        id: ids.next(),
        net: Some(NetId(net)),
        layer,
        width: len(width),
        geom: TrackGeom::Segment { start: a, end: b },
    }
}

/// A 30 x 20 mm two-layer RC low-pass board: a two-pin header, a resistor, a capacitor, three
/// tracks on the front, one via and a ground return on the back.
pub fn sample_board() -> Board {
    let mut ids = Ids(0);
    let mut b = Board::new("rc-lowpass", 2).unwrap();
    b.outline = Some(Outline::rectangle(0, 0, len(30.0), len(20.0)));
    for (i, name) in ["VCC", "GND", "SIG"].iter().enumerate() {
        b.nets.push(Net {
            id: NetId(i as u32 + 1),
            name: (*name).into(),
            class: DEFAULT_CLASS.into(),
        });
    }
    let j1 = vec![
        header_pad(&mut ids, "1", 1, mm(0.0, -1.27)),
        header_pad(&mut ids, "2", 2, mm(0.0, 1.27)),
    ];
    let r1 = vec![
        smd(&mut ids, "1", 1, mm(-1.0, 0.0)),
        smd(&mut ids, "2", 3, mm(1.0, 0.0)),
    ];
    let c1 = vec![
        smd(&mut ids, "1", 3, mm(-1.0, 0.0)),
        smd(&mut ids, "2", 2, mm(1.0, 0.0)),
    ];
    let fp = footprint(&mut ids, "J1", "Input", "PinHeader_1x02", mm(5.0, 10.0), j1);
    b.footprints.push(fp);
    let fp = footprint(&mut ids, "R1", "10k", "R_0603", mm(14.0, 8.73), r1);
    b.footprints.push(fp);
    let fp = footprint(&mut ids, "C1", "100n", "C_0603", mm(22.0, 8.73), c1);
    b.footprints.push(fp);

    let f = Layer::FCu;
    let t = segment(&mut ids, 1, f, 0.3, mm(5.0, 8.73), mm(13.0, 8.73));
    b.tracks.push(t);
    let t = segment(&mut ids, 3, f, 0.25, mm(15.0, 8.73), mm(21.0, 8.73));
    b.tracks.push(t);
    let t = segment(&mut ids, 2, f, 0.3, mm(23.0, 8.73), mm(23.0, 13.0));
    b.tracks.push(t);
    b.vias.push(Via {
        id: ids.next(),
        net: Some(NetId(2)),
        position: mm(23.0, 13.0),
        diameter: len(0.8),
        drill: len(0.4),
        kind: ViaKind::Through,
        from: Layer::FCu,
        to: Layer::BCu,
        tented: true,
    });
    let back = Layer::BCu;
    let t = segment(&mut ids, 2, back, 0.3, mm(23.0, 13.0), mm(5.0, 13.0));
    b.tracks.push(t);
    let t = segment(&mut ids, 2, back, 0.3, mm(5.0, 13.0), mm(5.0, 11.27));
    b.tracks.push(t);
    b
}

fn example_path() -> std::path::PathBuf {
    std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../examples/sample-board.circuito-pcb")
}

#[test]
fn the_sample_board_is_valid_and_clean() {
    let b = sample_board();
    b.validate().unwrap();
    let rules = CapabilityProfile::generic_2layer().rules();
    let report = run_drc(&b, &rules).unwrap();
    assert!(
        report.is_clean(),
        "unexpected findings: {:#?}",
        report.violations
    );
    assert!(check_profile(&b, &CapabilityProfile::generic_2layer())
        .unwrap()
        .is_empty());
    // And the manufacturing outputs come out.
    let g = gerber::write_all(&b, &gerber::GerberOptions::default()).unwrap();
    assert!(g.files.len() >= 9, "{} gerber files", g.files.len());
    assert!(g.warnings.is_empty(), "{:?}", g.warnings);
    let d = excellon::write_drills(&b, &excellon::DrillOptions::default()).unwrap();
    assert!(!d.files.is_empty());
}

#[test]
fn the_shipped_file_is_what_the_generator_writes() {
    let want = sample_board().to_json().unwrap();
    let path = example_path();
    if std::env::var_os("CIRCUITO_UPDATE_EXAMPLES").is_some() {
        std::fs::write(&path, &want).unwrap();
    }
    let have = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e}; run with CIRCUITO_UPDATE_EXAMPLES=1",
            path.display()
        )
    });
    assert_eq!(have, want, "examples/sample-board.circuito-pcb is stale");
}
